NEW_FILES = {'tests/test_canopy_column.py': '"""canopy_column: minted 2026-10-29 by tools/new_species.py (roadmap 150)."""\nfrom zoo_keeper.core import genome, kit\n\n\ndef test_canopy_column_is_discovered_and_validates():\n    assert "canopy_column" in genome.list_species()\n    assert genome.validate_genome(genome.load_species("canopy_column")) == []\n\n\ndef test_canopy_column_plans_at_its_authored_dims():\n    plan = kit.plan_kit({"building_id": "t", "slots": [{\n        "slot_id": "canopy_column_0", "role": "prop", "size_mod": "full", "style": 1,\n        "species": "canopy_column",\n        "fit": {"dims": [0.5, 0.5, 4.9], "pivot": "center"}}]},\n        theme="delco", style=1)\n    assert plan["species_fallbacks"] == []\n    assert plan["modules"][0]["species"] == "canopy_column"\n\n\nimport pytest  # noqa: E402\n\nfrom zoo_keeper.core import canopy_forms as CC  # noqa: E402\n\n\n@pytest.mark.parametrize("w,d,h", ((0.5, 0.5, 4.9), (0.4, 0.4, 5.0)))\ndef test_the_column_is_its_slot_a_guard_at_its_foot_and_a_shaft_to_the_soffit(w, d, h):\n    """FAILS ON 1.148.0: no species, and every canopy column shipped as its greybox box."""\n    (g, glo, ghi), (s, slo, shi) = CC.column_boxes(w, d, h)\n    assert (glo[0], glo[1], glo[2]) == pytest.approx((-w / 2, -d / 2, -h / 2))\n    assert (ghi[0], ghi[1]) == pytest.approx((w / 2, d / 2))\n    assert shi[2] == pytest.approx(h / 2) and slo[2] < ghi[2]          # to the soffit, rising out of the guard\n    assert shi[0] < w / 2 and shi[1] < d / 2\n', 'tests/test_fuel_canopy.py': '"""fuel_canopy: minted 2026-10-29 by tools/new_species.py (roadmap 150)."""\nfrom zoo_keeper.core import genome, kit\n\n\ndef test_fuel_canopy_is_discovered_and_validates():\n    assert "fuel_canopy" in genome.list_species()\n    assert genome.validate_genome(genome.load_species("fuel_canopy")) == []\n\n\ndef test_fuel_canopy_plans_at_its_authored_dims():\n    plan = kit.plan_kit({"building_id": "t", "slots": [{\n        "slot_id": "fuel_canopy_0", "role": "prop", "size_mod": "full", "style": 1,\n        "species": "fuel_canopy",\n        "fit": {"dims": [22.0, 13.0, 0.9], "pivot": "center"}}]},\n        theme="delco", style=1)\n    assert plan["species_fallbacks"] == []\n    assert plan["modules"][0]["species"] == "fuel_canopy"\n\n\nimport pytest  # noqa: E402\n\nfrom zoo_keeper.core import price_pylon_forms as PF  # noqa: E402\nfrom zoo_keeper.core import canopy_forms as FC  # noqa: E402\n\nDECKS = ((22.0, 13.0, 0.9), (24.0, 10.0, 0.4))        # the two decks Deli Counter\'s specs author\n\n\ndef _span(boxes, axis):\n    return min(lo[axis] for _n, lo, _hi in boxes), max(hi[axis] for _n, _lo, hi in boxes)\n\n\n@pytest.mark.parametrize("w,d,h", DECKS)\ndef test_the_deck_is_the_slot_exactly_and_its_soffit_is_the_lamps_plane(w, d, h):\n    """The canopy\'s lamps hang 2 cm under the slot\'s bottom (Deli Counter lights._CANOPY_DROP): the soffit\'s\n    underside must be that bottom, and nothing may stand outside the slot."""\n    b = FC.boxes(w, d, h)\n    assert _span(b, 0) == pytest.approx((-w / 2, w / 2))\n    assert _span(b, 1) == pytest.approx((-d / 2, d / 2))\n    assert _span(b, 2) == pytest.approx((-h / 2, h / 2))\n    soffit = [x for x in b if x[0] == "Soffit"]\n    assert soffit and soffit[0][1][2] == pytest.approx(-h / 2)\n\n\n@pytest.mark.parametrize("w,d,h", DECKS)\ndef test_no_two_parts_of_one_colour_overlap_and_the_soffit_and_cap_abut_the_ring(w, d, h):\n    """Overlap is a volume shared by two boxes; abutting boxes share a face and no volume. The soffit and the cap\n    stand on the ring\'s inner faces, so their undersides and the ring\'s are never one plane over shared ground."""\n    b = FC.boxes(w, d, h)\n\n    def vol(p, q):\n        out = 1.0\n        for i in range(3):\n            out *= max(0.0, min(p[2][i], q[2][i]) - max(p[1][i], q[1][i]))\n        return out\n\n    ring = [x for x in b if x[0] in ("Fascia", "FasciaEnds")]\n    for part in [x for x in b if x[0] in ("Soffit", "Cap")]:\n        assert all(vol(part, r) == pytest.approx(0.0, abs=1e-12) for r in ring), part\n    for i, p in enumerate(ring):\n        for q in ring[i + 1:]:\n            assert vol(p, q) == pytest.approx(0.0, abs=1e-12)\n\n\ndef test_the_fascia_and_the_stripe_are_the_stores_colours():\n    for v in range(len(PF.COLOURWAYS)):\n        field, rule, _ink = PF.COLOURWAYS[v]\n        f, s = FC.colours(v)\n        assert f == pytest.approx(tuple(c / 255 for c in field)) and s == pytest.approx(tuple(c / 255 for c in rule))\n\n\n@pytest.mark.parametrize("w,d,h", DECKS)\ndef test_bpy_the_deck_builds_to_its_slot_in_one_material(tmp_path, w, d, h):\n    pytest.importorskip("bpy")\n    import bpy\n    from zoo_keeper.bpylayer import build\n    plan = kit.plan_kit({"building_id": "t", "slots": [{\n        "slot_id": "canopy_roof", "role": "prop", "size_mod": "full", "style": 1, "species": "fuel_canopy",\n        "fit": {"dims": [w, d, h], "pivot": "center"}}]}, theme="delco_1997", style=1)\n    res = build.build_module(plan["modules"][0], str(tmp_path), theme="delco_1997", style=1,\n                             options={"save_blend": False})\n    assert res["report"]["status"] == "pass", res["report"]["checks"]\n    meshes = [o for o in bpy.data.objects if o.type == "MESH" and not o.name.endswith("-colonly")]\n    assert {m.name for o in meshes for m in o.data.materials} and \\\n        len({m.name for o in meshes for m in o.data.materials}) == 1\n', 'zoo_keeper/core/canopy_forms.py': '"""The filling station canopy\'s shapes, pure (the factory\'s roadmap 324): the deck (`recipes/fuel_canopy`) and its\ncolumns (`recipes/canopy_column`). The recipes build these boxes; the tests read them without Blender. Each recipe\'s\ndocstring says why its parts are where they are.\n"""\nfrom __future__ import annotations\n\nfrom . import price_pylon_forms as PF\n\nFASCIA_T = 0.10          # the fascia ring\'s thickness, inward from its face\nSTRIPE_PROUD = 0.004     # the stripe stands this far proud of the fascia; the module\'s sides are its outer faces\nSTRIPE_H = 0.08          # the stripe\'s height; it sits STRIPE_AT of the fascia\'s height up from its foot\nSTRIPE_AT = 0.62\nSOFFIT_T = 0.04\nCAP_T = 0.03\nBURY = 0.004\nSHY = 0.003\n\nSOFFIT_RGB = (0.86, 0.86, 0.83)\nCAP_RGB = (0.42, 0.43, 0.45)\n\n\ndef colours(variant):\n    """(fascia, stripe) for the store\'s colourway ``variant``, 0..1."""\n    field, rule, _ink = PF.COLOURWAYS[int(variant) % len(PF.COLOURWAYS)]\n    return tuple(c / 255.0 for c in field), tuple(c / 255.0 for c in rule)\n\n\ndef boxes(w, d, h):\n    """The deck\'s parts as (name, lo, hi) boxes, centre pivot -- pure, for the tests."""\n    sp, ft = STRIPE_PROUD, FASCIA_T\n    x1, y1, z0, z1 = w / 2.0, d / 2.0, -h / 2.0, h / 2.0\n    fx, fy = x1 - sp, y1 - sp                      # the fascia\'s outer faces\n    zs0 = z0 + h * STRIPE_AT - STRIPE_H / 2.0\n    zs1 = zs0 + STRIPE_H\n    out = [\n        # the fascia ring: N and S the whole width, E and W between their backs\n        ("Fascia", (-fx, fy - ft, z0), (fx, fy, z1)),\n        ("Fascia", (-fx, -fy, z0), (fx, -fy + ft, z1)),\n        ("FasciaEnds", (fx - ft, -fy + ft, z0), (fx, fy - ft, z1)),\n        ("FasciaEnds", (-fx, -fy + ft, z0), (-fx + ft, fy - ft, z1)),\n        # the stripe on its face, the module\'s side its outer face; N and S the whole width, E and W to their backs\n        ("Stripe", (-x1, fy - BURY, zs0), (x1, y1, zs1)),\n        ("Stripe", (-x1, -y1, zs0), (x1, -fy + BURY, zs1)),\n        ("StripeEnds", (fx - BURY, -fy + BURY, zs0), (x1, fy - BURY, zs1)),\n        ("StripeEnds", (-x1, -fy + BURY, zs0), (-fx + BURY, fy - BURY, zs1)),\n        # the soffit, its underside the module\'s bottom, its edges ON the ring\'s inner faces: abutting, never\n        # overlapping -- buried, its underside and the ring\'s would be one plane facing one way, a z-fight seen from\n        # the forecourt\n        ("Soffit", (-fx + ft, -fy + ft, z0), (fx - ft, fy - ft, z0 + SOFFIT_T)),\n        # the roof cap, SHY under the ring\'s top, its edges on the ring\'s inner faces\n        ("Cap", (-fx + ft, -fy + ft, z1 - SHY - CAP_T), (fx - ft, fy - ft, z1 - SHY)),\n    ]\n    return out\n\n\n#: THE FACES NOBODY SEES, dropped by part (the house pattern, `geometry.drop_faces`): the E and W runs\' ends stand\n#: against the N and S runs\' backs, and the soffit\'s and the cap\'s sides against the ring\'s inner faces. Kept, each\n#: was a coincident pair in `tools/coplanar_census.py` (12 at the genome\'s smallest corner).\nHIDDEN = {"FasciaEnds": "ends", "StripeEnds": "ends", "Soffit": "sides", "Cap": "sides"}\n\n\ndef hidden(part, normal) -> bool:\n    """Whether a face of ``part`` with outward ``normal`` stands against another part."""\n    nx, ny, nz = normal\n    rule = HIDDEN.get(part)\n    if rule == "ends":\n        return abs(ny) > 0.9\n    if rule == "sides":\n        return abs(nz) < 0.1\n    return False\n\n\n\nGUARD_H = 0.9            # a forecourt column\'s concrete guard: about a bumper\'s height and a half\nSHAFT = 0.6              # the shaft\'s side, as a share of the slot\'s narrower side\n\nGUARD_RGB = (0.88, 0.72, 0.16)\nSHAFT_RGB = (0.86, 0.86, 0.83)\n\n\ndef column_boxes(w, d, h):\n    """The column\'s parts as (name, lo, hi), centre pivot -- pure, for the tests."""\n    z0, z1 = -h / 2.0, h / 2.0\n    gh = min(GUARD_H, h / 5.0)\n    s = min(w, d) * SHAFT / 2.0\n    return [("Guard", (-w / 2.0, -d / 2.0, z0), (w / 2.0, d / 2.0, z0 + gh)),\n            ("Shaft", (-s, -s, z0 + gh - BURY), (s, s, z1))]\n\n\n', 'zoo_keeper/genome/species/canopy_column.json': '{\n "species": "canopy_column",\n "version": 1,\n "license": {\n  "construction_knowledge": "CC0",\n  "notes": "Minted 2026-10-29 by tools/new_species.py from \'prop\': a placeholder box at the authored dims until the recipe is shaped. NO REFERENCE GIVEN: look at ten photographs of one before drawing it."\n },\n "dimensions": {\n  "width": {\n   "min": 0.3,\n   "max": 1.0,\n   "default": 0.5\n  },\n  "depth": {\n   "min": 0.3,\n   "max": 1.0,\n   "default": 0.5\n  },\n  "height": {\n   "min": 3.0,\n   "max": 7.0,\n   "default": 4.9\n  }\n },\n "parts": [\n  "CanopyColumn_Guard",\n  "CanopyColumn_Shaft"\n ],\n "params": {},\n "materials": {\n  "default": "metal_painted",\n  "options": [\n   "metal_painted"\n  ]\n },\n "styles": {\n  "default": {\n   "material": "metal_painted",\n   "color": [\n    0.56,\n    0.55,\n    0.53\n   ],\n   "wear": 0.15,\n   "bevel": 0.006\n  },\n  "delco": {\n   "material": "metal_painted",\n   "color": [\n    0.5,\n    0.49,\n    0.46\n   ],\n   "wear": 0.35,\n   "bevel": 0.006,\n   "ambient": 0.35\n  },\n  "center_city": {\n   "material": "metal_painted",\n   "color": [\n    0.56,\n    0.5655,\n    0.58\n   ],\n   "wear": 0.122,\n   "bevel": 0.006,\n   "ambient": 0.15\n  },\n  "industrial_flats": {\n   "material": "metal_painted",\n   "color": [\n    0.4708,\n    0.4463,\n    0.4367\n   ],\n   "wear": 0.57,\n   "bevel": 0.006,\n   "ambient": 0.45\n  },\n  "rockay": {\n   "material": "metal_painted",\n   "color": [\n    0.5264,\n    0.5445,\n    0.5565\n   ],\n   "wear": 0.29,\n   "bevel": 0.006,\n   "ambient": 0.05\n  }\n },\n "budgets": {\n  "tris_lod0": 120\n },\n "attachments": [],\n "collision": true,\n "match_priority": 0,\n "keywords": [\n  "canopy column",\n  "canopy col",\n  "forecourt column",\n  "canopy_col"\n ]\n}\n', 'zoo_keeper/genome/species/fuel_canopy.json': '{\n "species": "fuel_canopy",\n "version": 1,\n "license": {\n  "construction_knowledge": "CC0",\n  "notes": "Minted 2026-10-29 by tools/new_species.py from \'prop\': a placeholder box at the authored dims until the recipe is shaped. NO REFERENCE GIVEN: look at ten photographs of one before drawing it."\n },\n "dimensions": {\n  "width": {\n   "min": 10.0,\n   "max": 40.0,\n   "default": 22.0\n  },\n  "depth": {\n   "min": 5.0,\n   "max": 26.0,\n   "default": 13.0\n  },\n  "height": {\n   "min": 0.3,\n   "max": 1.8,\n   "default": 0.9\n  }\n },\n "parts": [\n  "FuelCanopy_Fascia",\n  "FuelCanopy_FasciaEnds",\n  "FuelCanopy_Stripe",\n  "FuelCanopy_StripeEnds",\n  "FuelCanopy_Soffit",\n  "FuelCanopy_Cap"\n ],\n "params": {},\n "materials": {\n  "default": "metal_painted",\n  "options": [\n   "metal_painted"\n  ]\n },\n "styles": {\n  "default": {\n   "material": "metal_painted",\n   "color": [\n    0.56,\n    0.55,\n    0.53\n   ],\n   "wear": 0.15,\n   "bevel": 0.006\n  },\n  "delco": {\n   "material": "metal_painted",\n   "color": [\n    0.5,\n    0.49,\n    0.46\n   ],\n   "wear": 0.35,\n   "bevel": 0.006,\n   "ambient": 0.35\n  },\n  "center_city": {\n   "material": "metal_painted",\n   "color": [\n    0.56,\n    0.5655,\n    0.58\n   ],\n   "wear": 0.122,\n   "bevel": 0.006,\n   "ambient": 0.15\n  },\n  "industrial_flats": {\n   "material": "metal_painted",\n   "color": [\n    0.4708,\n    0.4463,\n    0.4367\n   ],\n   "wear": 0.57,\n   "bevel": 0.006,\n   "ambient": 0.45\n  },\n  "rockay": {\n   "material": "metal_painted",\n   "color": [\n    0.5264,\n    0.5445,\n    0.5565\n   ],\n   "wear": 0.29,\n   "bevel": 0.006,\n   "ambient": 0.05\n  }\n },\n "budgets": {\n  "tris_lod0": 240\n },\n "attachments": [],\n "collision": true,\n "match_priority": 0,\n "keywords": [\n  "fuel canopy",\n  "gas station canopy",\n  "forecourt canopy",\n  "canopy_roof"\n ]\n}\n', 'zoo_keeper/recipes/canopy_column.py': '"""canopy_column recipe: a filling station canopy\'s column -- a painted steel shaft on a concrete guard a bumper meets\nfirst, the guard in safety yellow.\n\nMinted by `tools/new_species.py`; shaped here (the factory\'s roadmap 324), beside `fuel_canopy`: Deli Counter\'s specs\nauthor six `canopy_col` volumes a canopy, and until this species each shipped as its greybox box.\n\nONE MATERIAL, colour in the `Wear` vertex colour (`geometry.tint_wear`). THE ENVELOPE IS THE SLOT\'S: the guard is the\nslot\'s full plan to `GUARD_H` (or a fifth of the height, the smaller); the shaft rises from inside it, buried by\n`BURY`, to the module\'s top -- the canopy\'s soffit, which owns that plane overhead.\n"""\nfrom __future__ import annotations\n\nfrom ..bpylayer import geometry, materials\nfrom ..core.canopy_forms import GUARD_RGB, SHAFT_RGB\nfrom ..core.canopy_forms import column_boxes as boxes\n\n\ndef build(plan, streams, collection):\n    w = plan["dimensions"]["width"]\n    d = plan["dimensions"]["depth"]\n    h = plan["dimensions"]["height"]\n    rng = streams.stream("wear")\n    rgb = {"Guard": GUARD_RGB, "Shaft": SHAFT_RGB}\n    objs = []\n    for name, lo, hi in boxes(w, d, h):\n        bm = geometry.new_bm()\n        geometry.add_box(bm, tuple((lo[i] + hi[i]) / 2.0 for i in range(3)), tuple(hi[i] - lo[i] for i in range(3)))\n        o = geometry.bm_to_object(bm, f"CanopyColumn_{name}", collection, bevel=plan["bevel"], texel=1.2, rng=rng,\n                                  wear=plan["wear"])\n        geometry.tint_wear(o, rgb[name])\n        objs.append(o)\n    surface = materials.make_material(f"M_CanopyColumn_{plan[\'material\']}", plan["color"], plan["material"])\n    materials.assign(objs, surface)\n    return {"objects": objs, "collision_boxes": [((-w / 2, -d / 2, -h / 2), (w / 2, d / 2, h / 2))],\n            "attachments": {"ATT_top": (0.0, 0.0, h / 2)}}\n', 'zoo_keeper/recipes/fuel_canopy.py': '"""fuel_canopy recipe: a filling station\'s canopy deck -- a fascia band in the store\'s colour all round, a stripe in\nits rule colour along the fascia, a light soffit under it and a roof cap over it.\n\nMinted by `tools/new_species.py`; shaped here (the factory\'s roadmap 324). The walker, 2026-10-29, of the game\'s\nvertical slice: "Things still look simple, and computer made". Deli Counter\'s specs author the canopy as a volume,\n`canopy_roof`, and until this species nothing built it: the forecourt\'s landmark shipped as its greybox box, a grey\nslab with the canopy\'s lights under it (the factory\'s docs/findings/slice_look/, slice 6).\n\nTHE COLOURS ARE THE STORE\'S. A 1990s canopy\'s fascia is the brand\'s: the price pylon at the same frontage paints\nFLAPPAHS in `price_pylon_forms.COLOURWAYS` by its variant, and the deck takes the same variant\'s field for the fascia\nand its rule for the stripe, so the canopy and the sign out front are one brand.\n\nONE MATERIAL: fascia, stripe, soffit and cap are colour only, in the `Wear` vertex colour (`geometry.tint_wear`), as\n`drive_up_canopy` does: one submission for the whole deck.\n\nTHE ENVELOPE IS THE SLOT\'S, EXACTLY: the stripe\'s outer faces are the module\'s sides; the fascia stands\n`STRIPE_PROUD` inside them; the soffit\'s underside is the module\'s bottom face -- the plane Deli Counter\'s canopy\nlights hang from (`lights._CANOPY_DROP`), so Lux\'s lamps stay where they were. The corners close as the coping\'s do:\nthe N and S fascia and stripes run the whole width, the E and W stop at their backs. Nothing is coplanar with\nanything it overlaps: the soffit and the cap ABUT the fascia ring\'s inner faces, the cap `SHY` under its top, and the\nstripes are buried `BURY` into the fascia they stand on.\n"""\nfrom __future__ import annotations\n\nfrom ..bpylayer import geometry, materials\nfrom ..core.canopy_forms import CAP_RGB, SOFFIT_RGB, boxes, colours, hidden\n\n\ndef build(plan, streams, collection):\n    w = plan["dimensions"]["width"]\n    d = plan["dimensions"]["depth"]\n    h = plan["dimensions"]["height"]\n    wear = plan["wear"]\n    variant = int((plan.get("module") or {}).get("variant") or (plan.get("params") or {}).get("variant") or 0)\n    rng = streams.stream("wear")\n    fascia_rgb, stripe_rgb = colours(variant)\n    rgb = {"Fascia": fascia_rgb, "FasciaEnds": fascia_rgb, "Stripe": stripe_rgb, "StripeEnds": stripe_rgb,\n           "Soffit": SOFFIT_RGB, "Cap": CAP_RGB}\n    objs = []\n    by = {}\n    for name, lo, hi in boxes(w, d, h):\n        by.setdefault(name, []).append((lo, hi))\n    for name, parts in by.items():\n        bm = geometry.new_bm()\n        for lo, hi in parts:\n            geometry.add_box(bm, tuple((lo[i] + hi[i]) / 2.0 for i in range(3)),\n                             tuple(hi[i] - lo[i] for i in range(3)))\n        geometry.drop_faces(bm, lambda nrm, part=name: hidden(part, nrm))\n        o = geometry.bm_to_object(bm, f"FuelCanopy_{name}", collection, bevel=0.0, texel=1.2, rng=rng, wear=wear)\n        geometry.tint_wear(o, rgb[name])\n        objs.append(o)\n    surface = materials.make_material(f"M_FuelCanopy_{plan[\'material\']}", plan["color"], plan["material"])\n    materials.assign(objs, surface)\n    return {"objects": objs, "collision_boxes": [((-w / 2, -d / 2, -h / 2), (w / 2, d / 2, h / 2))],\n            "attachments": {"ATT_top": (0.0, 0.0, h / 2)}}\n'}


def _sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: %s/%s has mixed line endings; nothing written" % (REPO.name, name))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text) != PINS[name]:
        raise SystemExit("REFUSED: %s/%s is %s, not the %s this patch was written against; nothing written"
                         % (REPO.name, name, _sha(text), PINS[name]))
    return text, crlf > 0


def main():
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: %s/%s: the anchor at %s is there %d times; nothing written"
                                 % (REPO.name, name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name, text in WHOLE.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: %s/%s exists already; nothing written" % (REPO.name, name))
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).parent.mkdir(parents=True, exist_ok=True)
        (REPO / name).write_bytes(text.encode("utf-8"))
    print("%s: %d files edited, %d written" % (REPO.name, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
